INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q657620', 'Battle of Noreia', 'The Battle of Noreia, in 113 BC, was the opening battle of the Cimbrian War fought between the Roman Republic and the migrating Proto-Germanic tribes, the Cimbri and the Teutons. It ended in defeat, and near disaster, for the Romans.', -112, NULL, NULL, NULL, NULL, NULL, 'year', '112 BCE', 53, 'https://en.wikipedia.org/wiki/Battle_of_Noreia'),
  ('Q2236999', 'Battle of Mailberg', 'The Battle of Mailberg took place on 12 May 1082. The opponents were Vratislaus II of Bohemia (Czech: Vratislav II.) and Leopold II, Margrave of Austria (German: Luitpold II).', 1082, 5, 12, NULL, NULL, NULL, 'day', '12 May 1082', 39, 'https://en.wikipedia.org/wiki/Battle_of_Mailberg'),
  ('Q7510505', 'Siege of Vienna', 'The siege of Vienna was a decisive siege in 1485 of the Austrian–Hungarian War. It was a consequence of the ongoing conflict between Frederick III and Matthias Corvinus.', 1485, 1, 29, 1485, 6, 1, 'day', '29 January 1485 – 1 June 1485', 41, 'https://en.wikipedia.org/wiki/Siege_of_Vienna_(1485)'),
  ('Q477778', 'Battle of Frastanz', 'The Battle of Frastanz between an army of the Old Swiss Confederacy and the troops of King Maximilian I of the Holy Roman Empire took place on 20 April 1499. In one of the many raids of the Swabian War, an expedition of Habsburg troops had plundered some villages in the Swiss Confederacy, who responded by sending an army to Vorarlberg.', 1499, 4, 20, NULL, NULL, NULL, 'day', '20 April 1499', 41, 'https://en.wikipedia.org/wiki/Battle_of_Frastanz'),
  ('Q1398703', 'Battle of Hard', 'The Battle of Hard was the first large-scale battle in the Swabian War, waged between the Imperials under the Holy Roman Emperor Maximilian I and the Swiss Confederates. The battle was fought on 20 February 1499, a cold and foggy day, between 10,000 Imperial troops, mostly from the Swabian Circles, and a smaller number of Swiss troops, often called Reisläufer.', 1499, 2, 20, NULL, NULL, NULL, 'day', '20 February 1499', 37, 'https://en.wikipedia.org/wiki/Battle_of_Hard'),
  ('Q207576', 'First Turkish Siege of Vienna', 'The 1529 siege of Vienna was the first attempt by the Ottoman Empire to capture the city of Vienna in the Archduchy of Austria, part of the Holy Roman Empire. Suleiman the Magnificent, sultan of the Ottomans, attacked the city with over 100,000 men, while the defenders, led by Niklas Graf Salm, numbered no more than 21,000.', 1529, 9, 27, 1529, 10, 15, 'day', '27 September 1529 – 15 October 1529', 73, 'https://en.wikipedia.org/wiki/Siege_of_Vienna_(1529)'),
  ('Q368207', 'Battle of Leobersdorf', 'The Battle of Leobersdorf was fought near Leobersdorf on 19 September 1532, as part of the Habsburg–Ottoman War of 1526–1568.', 1532, 9, 19, NULL, NULL, NULL, 'day', '19 September 1532', 39, 'https://en.wikipedia.org/wiki/Battle_of_Leobersdorf'),
  ('Q74623', 'Great Turkish War', 'The Great Turkish War was a series of conflicts between the Ottoman Empire and the Holy League consisting of the Holy Roman Empire, Poland-Lithuania, Venice, Russia, and the Kingdom of Hungary. Intensive fighting began in 1683 and ended with the signing of the Treaty of Karlowitz in 1699.', 1683, NULL, NULL, 1699, NULL, NULL, 'year', '1683–1699', 76, 'https://en.wikipedia.org/wiki/Great_Turkish_War'),
  ('Q200855', 'Battle of Vienna', 'The Battle of Vienna took place at Kahlenberg Mountain near Vienna on 12 September 1683 after the city had been besieged by the Ottoman Empire for two months. The battle was fought between an Ottoman army commanded by Grand Vizier Kara Mustafa Pasha and a coalition of Imperial German and Polish Crown forces under the overall command of King John III Sobieski of the Polish–Lithuanian Commonwealth.', 1683, 9, 12, NULL, NULL, NULL, 'day', '12 September 1683', 79, 'https://en.wikipedia.org/wiki/Battle_of_Vienna'),
  ('Q7222682', 'Second Turkish Siege of Vienna', 'The Battle of Vienna took place at Kahlenberg Mountain near Vienna on 12 September 1683 after the city had been besieged by the Ottoman Empire for two months. The battle was fought between an Ottoman army commanded by Grand Vizier Kara Mustafa Pasha and a coalition of Imperial German and Polish Crown forces under the overall command of King John III Sobieski of the Polish–Lithuanian Commonwealth.', 1683, 7, 14, 1683, 9, 12, 'day', '14 July 1683 – 12 September 1683', 41, 'https://en.wikipedia.org/wiki/Second_Turkish_Siege_of_Vienna'),
  ('Q698176', 'Treaty of Vienna', 'The Peace of Vienna, also known as the First Treaty of Vienna, was a series of four treaties signed between 30 April 1725 and 5 November 1725 involving the Habsburg Monarchy, the Holy Roman Empire (on behalf of Austria), and Bourbon Spain. A new military alliance was formed, with the Russian Empire joining later in 1726.', 1725, 4, 30, NULL, NULL, NULL, 'day', '30 April 1725', 50, 'https://en.wikipedia.org/wiki/Treaty_of_Vienna_(1725)'),
  ('Q156086', 'Treaty of Aix-la-Chapelle', 'The 1748 Treaty of Aix-la-Chapelle, sometimes called the Treaty of Aachen, ended the War of the Austrian Succession, following a congress assembled on 24 April 1748 at the Free Imperial City of Aachen. The two main antagonists in the war, Britain and France, opened peace talks in the Dutch city of Breda in 1746.', 1748, 10, 18, NULL, NULL, NULL, 'day', '18 October 1748', 72, 'https://en.wikipedia.org/wiki/Treaty_of_Aix-la-Chapelle_(1748)'),
  ('Q9162412', 'Austrian occupation of Spiš and Podhale', 'Austrian occupation of Spiš and Podhale – the Austrian occupation of the Spiš lien from 1769 until 1772, when the occupied territory was formally annexed by the Habsburg Empire, part of the First Partition of Poland. Prior to the annexation, the territory was part of Poland proper, as part of the Crown of the Kingdom of Poland.', 1769, NULL, NULL, 1772, NULL, NULL, 'year', '1769–1772', 26, 'https://en.wikipedia.org/wiki/Austrian_occupation_of_Spi%C5%A1_and_Podhale'),
  ('Q2236891', 'Battle of Feldkirch', 'The Battle of Feldkirch (23 March 1799) saw some French corps led by André Masséna attack a weaker Austrian force under Franz Jellacic. Defending fortified positions, the Austrians repulsed all of the French columns, though the struggle lasted until nightfall.', 1799, 3, 23, NULL, NULL, NULL, 'day', '23 March 1799', 37, 'https://en.wikipedia.org/wiki/Battle_of_Feldkirch'),
  ('Q697034', 'Battle of Amstetten', 'The Battle of Amstetten was a minor engagement during the War of the Third Coalition between the First French Empire and the alliance of Austria and Russia. It occurred on 5 November 1805, when the retreating Russo-Austrian troops, led by Mikhail Kutuzov, were intercepted by Marshal Joachim Murat''s cavalry and a portion of Marshal Jean Lannes'' corps.', 1805, 11, 5, NULL, NULL, NULL, 'day', '5 November 1805', 47, 'https://en.wikipedia.org/wiki/Battle_of_Amstetten'),
  ('Q699665', 'Battle of Dürenstein', 'The Battle of Dürenstein (German: Schlacht bei Dürnstein; also known as Dürrenstein, Dürnstein and Diernstein) or the Battle of Krems (Russian: Сражение при Кремсе), on 11 November 1805, was an engagement in the Napoleonic Wars during the War of the Third Coalition. Dürenstein (modern Dürnstein), Austria, is located in the Wachau valley, on the river Danube, 73 kilometers (45 mi) upstream from Vienna, Austria.', 1805, 11, 11, NULL, NULL, NULL, 'day', '11 November 1805', 56, 'https://en.wikipedia.org/wiki/Battle_of_D%C3%BCrenstein'),
  ('Q948810', 'Battle of Schöngrabern', 'The Battle of Schöngrabern, also known as the Battle of Hollabrunn, was an engagement in the Napoleonic Wars during the War of the Third Coalition, fought on 16 November 1805 near Hollabrunn in Lower Austria, four weeks after the Battle of Ulm and two weeks before the Battle of Austerlitz (Slavkov, Moravia - now Czech Republic).', 1805, 11, 16, NULL, NULL, NULL, 'day', '16 November 1805', 52, 'https://en.wikipedia.org/wiki/Battle_of_Sch%C3%B6ngrabern'),
  ('Q952479', 'Battle of Mariazell', 'The Battle of Mariazell or Battle of Grossraming (8 November 1805) saw the advance guard of the French III Corps attack a retreating Austrian force led by Maximilian, Count of Merveldt. The action occurred during the War of the Third Coalition, which is part of the Napoleonic Wars.', 1805, 11, 8, NULL, NULL, NULL, 'day', '8 November 1805', 34, 'https://en.wikipedia.org/wiki/Battle_of_Mariazell'),
  ('Q1346666', 'Battle of Lambach', 'The Battle of Lambach (Russian: Бой при Ламбахе, French: Bataille de Lambach, German: Gefecht bei Lambach) was a minor French victory where the French vanguard won against an Austro-Russian force under Pjotr Bagration (Russia) and Emanuel Freiherr Schustekh (Austria) on 31 October 1805 at Lambach in Oberösterreich, today Austria, during the Napoleonic Wars.', 1805, 10, 31, 1805, 11, 1, 'day', '31 October 1805 – 1 November 1805', 34, 'https://en.wikipedia.org/wiki/Battle_of_Lambach'),
  ('Q1625621', 'Battle of Steyr', 'Battle of Steyr (French: Bataille de Steyr; German: Schlacht bei Steyr) was fought on 4 November 1805 between the French army under the command of Louis-Nicolas Davout and the Austrian army under the command of General Maximilian, Count of Merveldt during the War of the Third Coalition. It ended in French victory.', 1805, 11, 4, NULL, NULL, NULL, 'day', '4 November 1805', 34, 'https://en.wikipedia.org/wiki/Battle_of_Steyr'),
  ('Q2237017', 'Battle of Mehrnbach', 'The Battle of Mehrnbach (also known as the Battle of Ried) on 30 October 1805 saw the French vanguard commanded by Marc Antoine de Beaumont engaging an Austro-Russian rearguard detachment during the War of the Third Coalition.', 1805, 10, 30, NULL, NULL, NULL, 'day', '30 October 1805', 39, 'https://en.wikipedia.org/wiki/Battle_of_Mehrnbach'),
  ('Q467777', 'Battle of Wagram', 'The Battle of Wagram ([ˈvaɡram]; 5–6 July 1809) was a military engagement of the Napoleonic Wars that ended in a costly but decisive victory for Emperor Napoleon''s French and allied army against the Austrian army under the command of Archduke Charles of Austria-Teschen. The battle led to the breakup of the Fifth Coalition, the Austrian and British-led alliance against France.', 1809, 7, 5, 1809, 7, 6, 'day', '5 July 1809 – 6 July 1809', 71, 'https://en.wikipedia.org/wiki/Battle_of_Wagram'),
  ('Q541626', 'Battle of Aspern-Essling', 'In the Battle of Aspern–Essling (21–22 May 1809), Napoleon crossed the Danube near Vienna, but the French and their allies were attacked and forced back across the river by the Austrians under Archduke Charles. It was the first time Napoleon had been personally defeated in a major battle, as well as his first battle defeat in 10 years since the siege of Acre, and his first battle defeat as head of state, although he did suffer a tactical defeat in the Battle of Caldiero and in the Second Battle of Bassano.', 1809, 5, 21, 1809, 5, 22, 'day', '21 May 1809 – 22 May 1809', 67, 'https://en.wikipedia.org/wiki/Battle_of_Aspern%E2%80%93Essling'),
  ('Q744035', 'Battle of Ebelsberg', 'The Battle of Ebelsberg, known in French accounts as the Battle of Ebersberg, was fought on 3 May 1809 during the War of the Fifth Coalition, part of the Napoleonic Wars. The Austrian left wing under the command of Johann von Hiller took up positions at Ebersberg on the Traun river.', 1809, 5, 3, NULL, NULL, NULL, 'day', '3 May 1809', 47, 'https://en.wikipedia.org/wiki/Battle_of_Ebelsberg'),
  ('Q2984780', 'Battle of Graz', 'The Battle of Graz took place on 24–26 June 1809 between an Austrian corps commanded by Ignaz Gyulai and a French division led by Jean-Baptiste Broussier. The French were soon reinforced by a corps under Auguste Marmont.', 1809, 6, 24, 1809, 6, 26, 'day', '24 June 1809 – 26 June 1809', 34, 'https://en.wikipedia.org/wiki/Battle_of_Graz'),
  ('Q4871240', 'Battle of Hollabrunn', 'The Battle of Hollabrunn was a rearguard action fought on 9 July 1809 by Austrian VI Korps of the Kaiserlich-königliche Hauptarmee under Johann von Klenau against elements of the French IV Corps of the Armée d''Allemagne, under the command of André Masséna. The battle ended in favour of the Austrians, with Masséna forced to break off the combat and wait for his remaining divisions to reinforce him, but the French Marshal was able to gather crucial intelligence about the intentions of his enemy.', 1809, 7, 9, NULL, NULL, NULL, 'day', '9 July 1809', 37, 'https://en.wikipedia.org/wiki/Battle_of_Hollabrunn_(1809)'),
  ('Q4872295', 'Battle of Sankt Michael', 'In the Battle of Sankt Michael (or Sankt Michael-Leoben) on 25 May 1809, Paul Grenier''s French corps crushed Franz Jellacic''s Austrian division at Sankt Michael in Obersteiermark, Austria. The action occurred after the initial French victories during the War of the Fifth Coalition, part of the Napoleonic Wars.', 1809, 5, 25, NULL, NULL, NULL, 'day', '25 May 1809', 37, 'https://en.wikipedia.org/wiki/Battle_of_Sankt_Michael'),
  ('Q919739', 'Battle of Schwechat', 'The Battle of Schwechat was a battle in the Hungarian war of Independence of 1848-1849, fought on 30 October 1848 between the revolutionary Hungarian Army led by Lieutenant General János Móga against the army of the Austrian Empire led by Alfred I, Prince of Windisch-Grätz and Lieutenant General Josip Jelačić, at Schwechat, near Vienna. This was the last battle of 1848 in the Transdanubian campaign.', 1848, 10, 30, NULL, NULL, NULL, 'day', '30 October 1848', 39, 'https://en.wikipedia.org/wiki/Battle_of_Schwechat'),
  ('Q2406957', 'Vienna inflation riot', 'The Vienna inflation revolt, also known as the September riots, were riots following the labour demonstration and its violent suppression in Vienna on 17 September 1911. The event is marked as the bloodiest street clash in the history of the Austrian Empire since the 1848 October Uprising, as shots were fired on demonstrators for the first time in Vienna since 1848.', 1911, 9, 17, NULL, NULL, NULL, 'day', '17 September 1911', 26, 'https://en.wikipedia.org/wiki/Vienna_inflation_riot'),
  ('Q12805066', 'Judenburg Mutiny', 'The Judenburg mutiny was an armed rebellion that took place in the town of Judenburg, Austria-Hungary in May 1918. The mutiny was motivated by unwillingness of some military personnel to serve Austria-Hungary during the latter part of World War I. This incident came in the final stages of the war as a result of several other rebellions within the military of Austria-Hungary sparked by length of the conflict and a difficult situation on the Isonzo front.', 1918, 5, 12, NULL, NULL, NULL, 'day', '12 May 1918', 30, 'https://en.wikipedia.org/wiki/Judenburg_mutiny'),
  ('Q684762', 'July Revolt of 1927', 'The July Revolt of 1927 (also known as the Vienna Palace of Justice fire, German: Wiener Justizpalastbrand) was a major riot starting on 15 July 1927 in the Austrian capital, Vienna. The revolt was sparked by the acquittal of three nationalist paramilitary members for the killing of two social democratic Republikanischer Schutzbund members and culminated with police forces firing into the outraged crowd and killing 89 protesters, and five policemen died.', 1927, 7, 15, NULL, NULL, NULL, 'day', '15 July 1927', 55, 'https://en.wikipedia.org/wiki/July_Revolt_of_1927'),
  ('Q126604', 'First Vienna Award', 'The First Vienna Award was a treaty signed on 2 November 1938 pursuant to the Vienna Arbitration, which took place at Vienna''s Belvedere Palace. The arbitration and award were direct consequences of the previous month''s Munich Agreement, which resulted in the partitioning of Czechoslovakia.', 1938, 11, 2, NULL, NULL, NULL, 'day', '2 November 1938', 68, 'https://en.wikipedia.org/wiki/First_Vienna_Award'),
  ('Q334786', 'Austrian Anschluss referendum', 'A sham referendum on the Anschluss with Germany was held in German-occupied Austria on 10 April 1938, alongside one in Germany. German troops had already occupied Austria one month earlier, on 12 March 1938.', 1938, 4, 10, NULL, NULL, NULL, 'day', '10 April 1938', 53, 'https://en.wikipedia.org/wiki/1938_Austrian_Anschluss_referendum'),
  ('Q312388', 'Bleiburg repatriations', 'The Bleiburg repatriations (see terminology) were a series of forced repatriations from Allied-occupied Austria of Axis-affiliated individuals to Yugoslavia in May 1945 after the end of World War II in Europe. During World War II, Yugoslav territory was either annexed or occupied by Axis forces, and as the war came to end, thousands of Axis soldiers and civilian collaborators fled Yugoslavia for Austria as the Yugoslav Army (JA) gradually retook control.', 1945, 5, NULL, NULL, NULL, NULL, 'month', 'May 1945', 64, 'https://en.wikipedia.org/wiki/Bleiburg_repatriations'),
  ('Q829737', 'Deutsch Schützen massacre', 'The Deutsch Schützen massacre was a 1945 mass killing of at least 57 Hungarian Jewish forced laborers by the Waffen-SS in Deutsch Schützen-Eisenberg in Austria. The Hitler Youth-Bannführer Alfred Weber, who was responsible for construction in Deutsch Schützen, gave the order for the massacre.', 1945, 3, 29, NULL, NULL, NULL, 'day', '29 March 1945', 39, 'https://en.wikipedia.org/wiki/Deutsch_Sch%C3%BCtzen_massacre'),
  ('Q14303815', 'Battle of Castle Itter', 'The Battle of Castle Itter was fought on 5 May 1945, in the Austrian village of Itter in the North Tyrol region of the country, during the last days of the European Theater of World War II. Troops of the 23rd Tank Battalion of the 12th Armored Division of the US XXI Corps led by Lieutenant John C. "Jack" Lee Jr, a number of Wehrmacht soldiers led by Major Josef "Sepp" Gangl, SS-Hauptsturmführer Kurt-Siegfried Schrader, and recently freed French prisoners of war defended Castle Itter against an attacking force from the 17th SS Panzergrenadier Division until relief from the American 142nd…', 1945, 5, 5, NULL, NULL, NULL, 'day', '5 May 1945', 65, 'https://en.wikipedia.org/wiki/Battle_of_Castle_Itter'),
  ('Q1594779', 'Dachstein hiking disaster', 'In April 1954, 13 people from Heilbronn, ten students and three teachers, died in a blizzard while hiking the Dachstein Mountains in Upper Austria.', 1954, NULL, NULL, NULL, NULL, NULL, 'year', '1954', 34, 'https://en.wikipedia.org/wiki/Dachstein_hiking_disaster'),
  ('Q306535', 'Austrian State Treaty', 'The Austrian State Treaty (German: Österreichischer Staatsvertrag [ˈøːstɐraɪçɪʃɐ ˈʃtaːtsfɐˌtraːɡ] ) or Austrian Independence Treaty established Austria as a sovereign state. It was signed on 15 May 1955 in Vienna, at the Schloss Belvedere among the Allied occupying powers (France, the United Kingdom, the United States, and the Soviet Union) and the Austrian government.', 1955, 5, 15, NULL, NULL, NULL, 'day', '15 May 1955', 71, 'https://en.wikipedia.org/wiki/Austrian_State_Treaty'),
  ('Q918595', 'British Eagle International Airlines Flight 802', 'On Saturday, 29 February 1964, British Eagle International Airlines Flight 802/6 crashed into the Glungezer mountain near Innsbruck, Austria. The aircraft, a Bristol Britannia registered G-AOVO, had taken off from London Heathrow Airport, England, destined for Innsbruck Kranebitten Airport in Austria.', 1964, 2, 29, NULL, NULL, NULL, 'day', '29 February 1964', 47, 'https://en.wikipedia.org/wiki/British_Eagle_International_Airlines_Flight_802%2F6'),
  ('Q390871', 'Austrian nuclear power referendum', 'A referendum on the use of nuclear power was held in Austria on 5 November 1978. Voters were asked whether they approved a law allowing the peaceful use of nuclear power, particularly relating to the start-up of the Zwentendorf Nuclear Power Plant.', 1978, 11, 5, NULL, NULL, NULL, 'day', '5 November 1978', 48, 'https://en.wikipedia.org/wiki/1978_Austrian_nuclear_power_referendum'),
  ('Q623994', 'Strategic Arms Limitation Talks', 'The Strategic Arms Limitation Talks (SALT) were two rounds of bilateral conferences and corresponding international treaties involving the United States and the Soviet Union. The Cold War superpowers dealt with arms control in two rounds of talks and agreements: SALT I and SALT II. Negotiations commenced in Helsinki, in November 1969.', 1979, 6, 18, NULL, NULL, NULL, 'day', '18 June 1979', 69, 'https://en.wikipedia.org/wiki/Strategic_Arms_Limitation_Talks'),
  ('Q160056', 'Pan-European Picnic', 'The Pan-European Picnic (German: Paneuropäisches Picknick; Hungarian: Páneurópai piknik; Slovak: Paneurópsky piknik; Czech: Panevropský piknik) was a peace demonstration held on the Austro-Hungarian border near Sopron, Hungary, on 19 August 1989. The opening of the border gate between Austria and Hungary at the Pan-European Picnic was an event in the chain reaction, at the end of which Germany reunified, the Iron Curtain fell apart, and the Eastern Bloc disintegrated.', 1989, 8, 19, NULL, NULL, NULL, 'day', '19 August 1989', 68, 'https://en.wikipedia.org/wiki/Pan-European_Picnic'),
  ('Q2083813', '1999 Pentecost flood', 'The 1999 Pentecost flood (German: Pfingsthochwasser 1999) was a 100-year flood around the Pentecost season in 1999 that mostly affected Bavaria, Vorarlberg and Tirol. It was caused by heavy rainfall coinciding with the regular Alpine meltwater.', 1999, 5, NULL, NULL, NULL, NULL, 'month', 'May 1999', 37, 'https://en.wikipedia.org/wiki/1999_Pentecost_flood'),
  ('Q655671', 'Hapag-Lloyd Flight 3378', 'Hapag-Lloyd Flight 3378 (HF-3378) was a passenger service operated by Hapag-Lloyd Flug from Chania, on the island of Crete, Greece, to Hannover, Germany. On 12 July 2000, the aircraft flying the route, an Airbus A310, had 143 passengers and 8 crew on board, set off for Hannover leaving the landing gear fully extended, as a precaution, since a malfunction had prevented its proper retraction after take-off.', 2000, 7, 12, NULL, NULL, NULL, 'day', '12 July 2000', 45, 'https://en.wikipedia.org/wiki/Hapag-Lloyd_Flight_3378'),
  ('Q871885', '2009 European floods', 'The 2009 European floods were a series of natural disasters that took place in June 2009 in Central Europe. Austria, the Czech Republic, Germany, Hungary, Poland, Romania, Serbia, Slovakia and Turkey were all affected.', 2009, NULL, NULL, NULL, NULL, NULL, 'year', '2009', 37, 'https://en.wikipedia.org/wiki/2009_European_floods'),
  ('Q282940', '2010 Central European floods', 'The 2010 Central European floods were a devastating series of weather events which occurred across several Central European countries during May and June 2010. Poland was the worst affected.', 2010, 5, 14, 2010, 6, 9, 'day', '14 May 2010 – 9 June 2010', 50, 'https://en.wikipedia.org/wiki/2010_Central_European_floods'),
  ('Q15991234', 'Treaty Establishing the European Stability Mechanism', 'The Treaty Establishing the European Stability Mechanism was signed by the member states of the eurozone to found the European Stability Mechanism (ESM), an international organisation located in Luxembourg, to act as a permanent source of financial assistance for member states in financial difficulty, with a maximum lending capacity of €500 billion. It replaced two earlier temporary EU funding programmes: the European Financial Stability Facility (EFSF) and the European Financial Stabilisation Mechanism (EFSM).', 2012, 2, 2, NULL, NULL, NULL, 'day', '2 February 2012', 34, 'https://en.wikipedia.org/wiki/Treaty_establishing_the_European_Stability_Mechanism'),
  ('Q250241', '2013 Austrian conscription referendum', 'A non-binding referendum on ending conscription was held in Austria on 20 January 2013. The proposal was supported by the Social Democratic Party and the Green Party and opposed by the Austrian People''s Party and the FPÖ. Though constitutionally not obligated to act on, both parties in government stated that they would honour the results.', 2013, 1, 20, NULL, NULL, NULL, 'day', '20 January 2013', 55, 'https://en.wikipedia.org/wiki/2013_Austrian_conscription_referendum'),
  ('Q13415210', '2013 European floods', 'Extreme flooding in Central Europe began after several days of heavy rain in late May and early June 2013. Flooding and damages primarily affected south and east German states (Thuringia, Saxony, Saxony-Anhalt, Lower Saxony, Bavaria and Baden-Württemberg), western regions of the Czech Republic (Bohemia), and Austria.', 2013, 5, 28, 2013, 6, 5, 'day', '28 May 2013 – 5 June 2013', 53, 'https://en.wikipedia.org/wiki/2013_European_floods'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe'),
  ('Q101095813', '2020 Vienna attacks', 'On 2 November 2020, a series of shootings took place in Vienna, Austria a few hours before the city was scheduled to enter a lockdown as a result of the COVID-19 pandemic. A lone gunman started shooting in the busy city centre, killing four civilians and injuring 23 others, seven critically, including a police officer.', 2020, 11, 2, NULL, NULL, NULL, 'day', '2 November 2020', 69, 'https://en.wikipedia.org/wiki/2020_Vienna_attack'),
  ('Q121511279', '2023 Slovenia floods', 'In August 2023, major floods occurred in large part of Slovenia and neighbouring areas of Austria and Croatia due to heavy rain. Amongst others, the level of rivers Sava, Mur and Drava was exceptionally high.', 2023, 8, NULL, 2023, 8, 23, 'month', 'August 2023 – 23 August 2023', 43, 'https://en.wikipedia.org/wiki/2023_Slovenia_floods'),
  ('Q130297776', '2024 Central European floods', 'The 2024 Central European floods were a series of floods caused by a record heavy rainfall generated by Storm Boris, an extremely humid Genoa low. The flooding began in Austria and the Czech Republic, then spread to Poland, Romania and Slovakia, and then onwards to Germany and Hungary.', 2024, 9, NULL, NULL, NULL, NULL, 'month', 'September 2024', 57, 'https://en.wikipedia.org/wiki/2024_Central_European_floods'),
  ('Q137366682', '2025 Bulgarian protests', 'Protests began in Bulgaria on 26 November 2025 after the Zhelyazkov government announced a 2026 budget plan that would have increased taxes—specifically, the amounts individuals were to contribute to pension and social-security programs. The government suspended, then withdrew the budget, but demonstrations continued, with protestors demanding the resignation of the government and new elections.', 2025, 11, 26, NULL, NULL, NULL, 'day', '26 November 2025', 48, 'https://en.wikipedia.org/wiki/2025%E2%80%932026_Bulgarian_protests');
